type Props = {
  open: number
  active: number
  done: number
  className?: string
}

export function ProgressBar3Segment({ open, active, done, className }: Props) {
  const total = open + active + done
  if (total === 0) return null

  const openPct = (open / total) * 100
  const activePct = (active / total) * 100
  const donePct = (done / total) * 100

  return (
    <div className={`flex h-1.5 gap-0.5 rounded-progress overflow-hidden ${className ?? ''}`}>
      {donePct > 0 && (
        <div className="bg-progress-done rounded-progress" style={{ width: `${donePct}%` }} />
      )}
      {activePct > 0 && (
        <div className="bg-progress-active rounded-progress" style={{ width: `${activePct}%` }} />
      )}
      {openPct > 0 && (
        <div className="bg-progress-open rounded-progress" style={{ width: `${openPct}%` }} />
      )}
    </div>
  )
}
